@startuml

class Boeing {
  + name : string
}

class Airline {
  + name : string
  + registrationNumber : string
}

class Employee {
  + name : string
  + employeeId : string
}

class Salesperson {
  + salesRegion : string
}

class Contract {
  + contractId : string
  + deliveryConditions : string
  + legalAspects : string
}

class Acquisition {
  + model : string
  + negotiatedPrice : float
  + deliveryDate : date
  + customizations : string
}

class Airplane {
  + serialNumber : string
  + manufactureDate : date
}

Employee "1" -- "0..*" Salesperson
Salesperson "1" -- "0..*" Contract
Airline "1" -- "0..*" Contract
Contract "1" *-- "1..*" Acquisition
Acquisition "1" -- "1" Airplane
Airline "0..1" -- "0..*" Airline : daughterOf

Salesperson --|> Employee

@enduml

